import os, re, glob, difflib

def norm(s):
    s = s.lower().strip()
    s = s.replace('_', '').strip()
    s = re.sub(r'[^a-z0-9 ]+', '', s)
    s = re.sub(r'\s+', ' ', s).strip()
    return s

def sim(a, b):
    if a == b:
        return 1.0
    return difflib.SequenceMatcher(None, a, b).ratio()

def fuzzy_list_eq(a, b, thresh=0.8):
    if len(a) != len(b):
        return False
    if not a:
        return True
    good = sum(1 for x, y in zip(a, b) if sim(x, y) >= thresh)
    return good >= len(a) - (1 if len(a) > 3 else 0)

frames = []
for path in sorted(glob.glob('/app/ocr2/f*.txt')):
    txt = open(path, errors='ignore').read()
    moves = None
    m = re.search(r'Moves?[:\s]*([0-9OolIS]{1,4})', txt, re.I)
    if m:
        d = m.group(1).translate(str.maketrans('OolIS', '00115'))
        if d.isdigit():
            moves = int(d)
    cmds = []
    for line in txt.splitlines():
        mm = re.match(r'^\s*[>»=]\s*(.*)$', line)
        if mm:
            c = norm(mm.group(1))
            if c and not re.match(r'^(score|moves)', c):
                cmds.append(c)
    frames.append((os.path.basename(path), moves, cmds))

acc = []
first = True
for name, moves, cmds in frames:
    if not cmds:
        continue
    if first:
        # all but last (last may be mid-typing)
        acc = cmds[:-1] if len(cmds) > 1 else list(cmds)
        first = False
        continue
    best = None
    for j in range(len(cmds)):
        L = min(len(acc), len(cmds) - j)
        if L <= 0:
            continue
        if fuzzy_list_eq(acc[-L:], cmds[j:j + L]):
            if best is None or L > best[0]:
                best = (L, j)
    if best is None:
        # try to find last known command anywhere
        for j in range(len(cmds) - 1, -1, -1):
            for k in range(min(len(acc), 4), 0, -1):
                if sim(acc[-1], cmds[j]) >= 0.6:
                    best = (0, j + 1)
                    break
            if best:
                break
    if best is None:
        continue
    L, j = best
    acc.extend(cmds[j + L:])

# append final stable command
last_cmds = [c for _, _, cs in frames if cs for c in cs]
if last_cmds:
    tail = frames[-1][2]
    if tail and (not acc or sim(acc[-1], tail[-1]) < 0.99):
        acc.append(tail[-1])

print('frames', len(frames), 'commands', len(acc), 'last moves', [m for _, m, _ in frames if m][-5:])
for i, c in enumerate(acc, 1):
    print(i, repr(c))

